	/** Черновата от мокъпа; product_id по име в WC. Връща [cfg, report]. */
	public static function build( $resolve = true ) {
		$cfg = Config::defaults();
		$report = array();
		foreach ( self::products() as $p ) {
			$p = array_merge( Config::product_defaults(), $p );
			$p['product_id'] = $resolve ? Catalog::find_by_name( $p['name'] ) : 0;
			$report[ $p['key'] ] = $p['product_id'] ? '#' . $p['product_id'] : 'не е намерен';
			$cfg['products'][] = $p;
		}
		$cfg['fit'] = self::fit();
		$cfg['problems'] = self::problems();
		return array( $cfg, $report );
	}

	/** Прави черновата, ако изобщо няма store. Връща report или null. */
	public static function maybe_seed() {
		if ( Config::store_exists() ) { return null; }
		list( $cfg, $report ) = self::build( function_exists( 'wc_get_products' ) );
		Config::save_draft( $cfg );
		update_option( 'ansa_promo_seed_report', array( 'at' => current_time( 'mysql' ), 'products' => $report ), false );
		return $report;
	}
